// slack-notification-function.js
async function sendSlackNotification(message) {
  const queue = new NotificationQueue(1, 2000); // 동시 1개, 최소 2초 간격

  return queue.enqueue(async () => {
    for (let retry = 0; retry < 3; retry++) {
      try {
        const response = await fetch(process.env.SLACK_WEBHOOK_URL, {
          method: 'POST',
          body: JSON.stringify(message)
        });

        if (response.status === 429) {
          const retryAfter = response.headers['retry-after'] || (Math.pow(2, retry) * 2);
          await sleep(retryAfter * 1000);
          continue;
        }

        if (!response.ok) throw new Error(`Slack API: ${response.status}`);
        return response;

      } catch (error) {
        if (retry === 2) throw error;
        await sleep(Math.pow(2, retry) * 1000 + Math.random() * 1000);
      }
    }
  });
}
```

